(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pt"] = {"ui":{"skip":"Saltar para o conteúdo","back":"← Voltar ao AI-gile","lang.button":"Idioma: {name}","lang.dialog":"Escolhe um idioma","lang.search":"Pesquisar idiomas","lang.none":"Nenhum idioma encontrado","lang.notYet":"{name} ainda não está traduzido","theme.aria":"Alternar entre tema claro e escuro","theme.toLight":"Mudar para o tema claro","theme.toDark":"Mudar para o tema escuro","index.title":"AI-gile: a tua equipa de dev com IA, num só quadro","index.description":"O AI-gile é um quadro kanban para equipas de código com IA. Elas trabalham enquanto dormes; recebes uma pilha curta de coisas para decidir, testar e aceitar.","hero.logoAlt":"Ícone do quadro AI-gile","hero.h1.html":"A tua equipa de dev com IA, num só&nbsp;quadro.","hero.alpha":"🐣 Pré-alfa fechado","hero.alphaTitle":"Cedo e inacabado: obrigado por experimentares!","hero.lede":"Constroem enquanto dormes. Acordas com uma pilha curta: algumas perguntas, algumas coisas para testar, um ou dois diamantes roxos. Clica, aceita, volta ao teu café.","dl.windows":"Aplicação para Windows","dl.browser":"Usar no navegador","dl.soon":"Em breve","dl.notify":"🔔 Avisem-me quando abrir","dl.notifySmall":"Alfa ou beta","hero.secondary":"Ágil, mas a equipa nunca precisa de café em pé para a reunião diária. (Fazem-na na mesma.)","pitch.h2":"O AI-gile em quantas palavras quiseres","pitch.lede":"Escolhe um tamanho, de uma palavra a 144. Cada tamanho é uma descrição própria, escrita para ele. Arrasta o cursor ou usa as setas do teclado.","pitch.rangeLabel":"Tamanho em palavras","pitch.dice":"🎲 outra versão","pitch.words.one":"{n} palavra","pitch.words.other":"{n} palavras","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letras","pitch.chars.one":"{n} caráter","pitch.chars.other":"{n} carateres","count.line.html.one":"{n} cartão no quadro neste momento","count.line.html.other":"{n} cartões no quadro neste momento","features.aria":"O que faz","f.pile.h":"Uma pilha só para ti","f.pile.html":"<b>Para ti</b> reúne tudo o que está à tua espera, em todos os projetos: perguntas, coisas para testar, tarefas que só um humano pode fazer. A tua fila diz o que vem a seguir e quanto tempo demora.","f.sleep.h":"Equipas que trabalham enquanto dormes","f.sleep.p":"Cada projeto tem um líder e uma equipa de agentes de IA. Comenta num cartão e a equipa acorda, faz o trabalho e devolve-o com passos que um humano cansado consegue seguir.","f.tester.h":"Um testador de IA verifica primeiro","f.tester.p":"Antes de chegar a ti, um testador segue os passos numa cópia da aplicação e mostra o que viu, com uma captura de ecrã. Passa pelos aprovados e aceita com um clique.","f.proof.h":"Provas, não promessas","f.proof.p":"Cada entrega mostra o que mudou: os ficheiros, o diff, as capturas de ecrã. Sem abrir cada aplicação para ver se já está pronto.","f.chat.h":"Conversa com os teus líderes","f.chat.p":"Uma barra ao estilo do Discord: um ícone por projeto, diamantes roxos para o que precisa de ti. Manda uma ideia a um líder; ele transforma-a em cartões e num plano, com um botão ✅ Go.","f.tidy.h":"Mantém-se arrumado","f.tidy.p":"Cartões parecidos juntam-se num só, títulos confusos são corrigidos e uma verificação de tokens mantém o código enxuto. Menos coisas para alternar, menos em que pensar.","f.private.h":"Teu, no teu computador","f.private.li1":"O quadro corre na tua própria máquina e só responde a ti.","f.private.li2":"As DMs privadas entre pessoas têm encriptação de ponta a ponta.","f.private.li3":"Sem contas, sem rastreadores, sem cookies.","f.lang.h":"Na tua língua","f.lang.p":"Mais de 120 idiomas, do holandês, galês e japonês ao pirata, Yoda e klingon, com uma troca rápida para inglês nas palavras de programador.","tl.aria":"Cronologia, da primeira conversa ao plano","tl.h2":"Da primeira conversa ao que vem a seguir","tl.lede":"Datas e horas reais, no teu fuso horário. Depois de hoje é o plano, sem datas prometidas.","tl.today":"Hoje","tl.planned":"planeado","tl.cards.one":"{n} cartão","tl.cards.other":"{n} cartões","join.h2":"Junta-te","join.lede":"O AI-gile está a ser construído por um humano pequeno e por muitos agentes pacientes. Por agora é privado, num alfa fechado com amigos. Queres experimentar quando abrir?","join.btn":"Registar interesse","join.small":"Escrevemos-te por e-mail, mais nada","footer.tag":"AI-gile. Sem rastreadores, sem cookies, sem café em pé.","footer.licence":"Licença comercial","footer.status":"Estado","form.sending":"A enviar…","form.failed":"Não resultou: tenta outra vez mais tarde.","form.offline":"Não foi possível contactar o AI-gile: tenta outra vez mais tarde.","interest.title":"AI-gile: avisem-me quando o alfa abrir","interest.description":"Deixa o teu e-mail para saberes quando o alfa ou beta fechado do AI-gile abrir.","interest.h1":"🔔 Avisem-me quando abrir","interest.lede":"O AI-gile está em pré-alfa fechado. Deixa o teu e-mail e escrevemos uma vez, quando houver lugar para ti.","interest.email":"O teu e-mail","interest.which":"Que teste?","interest.alpha":"Alfa fechado: cedo, cru, com muitas mudanças","interest.beta":"Beta: mais firme, mais tarde","interest.both":"Tanto faz, o que vier primeiro","interest.submit":"Pôr-me na lista","interest.thanks":"Obrigado! Estás na lista.","interest.kept":"Guardamos só o teu e-mail e o teste escolhido, apenas para esta lista. Sem newsletter, sem rastreadores.","licence.title":"AI-gile: licença comercial","licence.description":"Vais usar o AI-gile na tua empresa? Pede uma licença comercial gratuita.","licence.h1":"📜 Licença comercial","licence.lede":"Vais usar o AI-gile no trabalho? Conta-nos quem és e o que fazes. Se fizer algum bem, a licença é gratuita.","licence.company":"Empresa","licence.website":"Site","licence.what":"O que fazes","licence.how":"Como isso ajuda o mundo","licence.email":"E-mail","licence.submit":"Pedir","licence.thanks":"Obrigado! Respondemos por e-mail.","status.title":"Estado do AI-gile","status.h1":"Estado do AI-gile","status.quiet":"Tudo calmo","status.checking":"A verificar…","status.offline":"Não é possível contactar o serviço de estado neste momento (a tentar de novo)","status.updated":"atualizado {ago}","status.justNow":"agora mesmo","status.min":"há {n} min","status.hours":"há {n} h","status.days":"há {n} d","live.h2":"Veja a ser construído, em direto","live.caption":"Cada cartão está escondido: vê a forma do trabalho, não as palavras.","live.watching.one":"em direto: {n} a ver","live.watching.other":"em direto: {n} a ver","live.offline":"O quadro em direto está a fazer uma pausa. Volte em breve.","live.cols":"Backlog|A fazer|Em curso|A equipa verifica|Para testares|Para a equipa|Concluído","live.last.now":"Último cartão movido agora mesmo","live.last.min.one":"Último cartão movido há {n} min","live.last.min.other":"Último cartão movido há {n} min","live.last.hour.one":"Último cartão movido há {n} hora","live.last.hour.other":"Último cartão movido há {n} horas","live.last.day.one":"Último cartão movido há {n} dia","live.last.day.other":"Último cartão movido há {n} dias"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robôs.","Delegado."]},{"n":2,"texts":["Kanban robótico.","Agentes, organizados.","Ideias, construídas."]},{"n":3,"texts":["Kanban para robôs.","Ideias viram funcionalidades.","Kanban de agentes, grátis."]},{"n":5,"texts":["Quadro kanban gerido por agentes.","Tu escreves cartões. Agentes constroem.","Grátis, local, testado, um pouco parvo."]},{"n":8,"texts":["Um kanban grátis onde agentes de IA trabalham.","Escreve uma ideia. Agentes constroem. Tu aceitas.","Ágil para um humano e muitos robôs pacientes."]},{"n":13,"texts":["Um quadro kanban no teu computador, onde agentes de IA pegam nos cartões.","Escreve uma ideia. Uma equipa de agentes constrói. Um testador verifica.","Grátis, sem contas, sem rastreadores: um quadro, uns robôs e tu no comando."]},{"n":21,"texts":["O AI-gile é um quadro kanban para trabalhar com agentes de código de IA. Eles pegam nos cartões; tu testas e aceitas.","Cada projeto tem um líder e uma equipa de agentes de IA. Comenta em qualquer cartão e a equipa mete mãos à obra.","Um quadro pessoal e gratuito que corre no teu próprio computador. Quem trabalha são robôs. Quem diz que sim és tu."]},{"n":34,"texts":["Pões ideias num quadro. Uma equipa de agentes de IA transforma-as em funcionalidades que funcionam, testa tudo e devolve com passos para experimentares. Nada conta como pronto até dizeres que sim.","O AI-gile é um quadro kanban caseiro que o Rich construiu com muita ajuda dos agentes que agora gere. É gratuito, corre no teu computador e é partilhado com amigos, não vendido.","Imagina um quadro kanban normal, com colunas do Backlog até Concluído, só que os cartões são pegos por agentes de IA. Contam o andamento, perguntam quando encravam e esperam sempre pelo teu polegar para cima."]},{"n":55,"texts":["O AI-gile é um quadro kanban em que a equipa é feita de agentes de IA. Cada projeto tem um líder que planeia o trabalho e ajudantes que o constroem. Quando uma funcionalidade fica pronta, um testador de IA experimenta-a e tira uma captura de ecrã, e depois cai na tua pilha. Aceita, ou comenta e eles refazem.","Começou como a maneira de uma pessoa acompanhar várias sessões de código com IA ao mesmo tempo e cresceu até ser um quadro a sério. Corre na tua máquina, não pede conta e não tem rastreadores. É grátis para amigos e curiosos. Também está inacabado, por isso espera arestas e uma surpresa de vez em quando.","Sejamos honestos. Ainda tens de ter as ideias e ainda tens de verificar os resultados. O que o AI-gile faz é tudo o que fica pelo meio: mantém os cartões por ordem, acorda o agente certo quando comentas, mostra exatamente o que mudou e junta tudo numa pilha curta para ti."]},{"n":89,"texts":["O AI-gile é um quadro kanban gratuito que corres no teu próprio computador. Em vez de pessoas, cada projeto tem uma equipa de agentes de IA: um líder que transforma as tuas ideias em cartões e num plano, e ajudantes que pegam nos cartões por ordem de prioridade. Quando algo fica pronto, um testador de IA segue os passos de teste e mostra o que viu. Depois fica à espera numa pilha chamada Para ti. Aceitas, ou comentas e a equipa tenta outra vez. Nada chega a Concluído sem ti.","Alguns recursos que talvez não esperes. Um vigia da noite mantém a coluna A fazer abastecida enquanto dormes, escolhendo cartões que não precisam de resposta tua. Um contador de tokens mostra quanto os agentes gastaram hoje e esta semana, e o Modo Sem Tokens manda-os parar de gastar. Podes conversar com amigos, e as mensagens privadas têm encriptação de ponta a ponta. O quadro fala cerca de 120 idiomas, entre eles holandês, flamengo, pirata e klingon. Nada disto custa um cêntimo, e ninguém te quer vender nada.","O AI-gile é um projeto pequeno e pessoal, não uma empresa. O Rich queria cuidar de vários projetos de código com IA sem abrir cada aplicação para espreitar, por isso ele e os agentes construíram um quadro para isso e depois usaram o quadro para construir o resto dele próprio. Está em pré-alfa fechado, ou seja, funciona, quase sempre, para um punhado de amigos. Não há página de preços, newsletter nem plano de crescimento. Se te parece útil, pede para experimentar quando abrir um pouco mais."]},{"n":144,"texts":["O AI-gile é um quadro kanban para um humano e muitos agentes de IA. Corre no teu próprio computador e é totalmente gratuito. Adicionas projetos, e cada projeto ganha um líder e uma equipa pequena. Conversas com o líder, mais ou menos como no Discord, e descreves uma ideia; o líder transforma-a em cartões e num plano, e espera que carregues em Go. A equipa vai passando pelos cartões por ordem de prioridade, usando uma linha de comandos simples feita para modelos de linguagem. Antes de qualquer coisa voltar para ti, um testador de IA segue os passos numa cópia da aplicação e anexa uma captura de ecrã. O trabalho pronto cai na tua pilha com os ficheiros alterados e o diff. Aceitas, ou deixas um comentário e a equipa acorda e tenta de novo. Só tu podes mover um cartão para Concluído.","Um dia com o AI-gile, mais ou menos. À noite deixas alguns comentários: este botão está no sítio errado, aquela lista devia estar ordenada, podíamos ter um modo escuro. Vais dormir. Os agentes lêem os comentários, fazem as alterações, testam e devolvem-te tudo. Se o A fazer esvazia, o vigia da noite volta a enchê-lo com cartões do backlog que não precisam de resposta tua. De manhã há uma pilha curta: algumas perguntas e algumas coisas para experimentar, cada uma com passos que uma pessoa ensonada consegue seguir e uma captura de ecrã a funcionar. Passas por tudo, aceitas o que está bom e devolves o resto. Um contador de tokens mostra o que tudo isto gastou, e o Modo Sem Tokens existe para as semanas magras. Depois tomas o pequeno-almoço, e aí os agentes ainda não ajudam.","Primeiro, o que o AI-gile não é. Não é uma startup, não está à venda e ninguém recolhe os teus dados. É um quadro gratuito que corre no teu computador, sem contas, sem rastreadores e sem cookies. O que é: um lugar arrumado para ver todos os teus projetos de código com IA de uma vez, com uma equipa de agentes a tratar dos cartões e tu a tomar as decisões. Junta cartões parecidos, corrige títulos confusos e vigia quão enxuto o código se mantém. Fala cerca de 120 idiomas, do holandês e do flamengo ao pirata e ao klingon. Os amigos podem trocar mensagens, em privado e encriptadas. Foi construído pelo Rich e por muitos agentes pacientes, usando-se a si próprio quase sempre. Está em pré-alfa fechado, por isso ainda é cru em alguns pontos. Se te parece divertido, pede com jeitinho e talvez entres mais cedo."]}],"quips":{"1":"Uma palavra. Ousado. Talvez demasiado ousado.","3":"Três palavras. Já mais honesto do que a maioria das páginas de produto.","8":"Oito palavras. Ainda mais curto do que uma reunião diária.","21":"Os tamanhos são story points, já agora. Claro que são.","55":"Cinquenta e cinco palavras. Dois cartões ficaram prontos enquanto lias.","144":"Esta é a longa. Não existe 233. Os agentes foram dormir."}},"timeline":{"first-idea.name":"A primeira ideia","first-idea.line":"A primeiríssima conversa, antes de existir qualquer código.","first-board.name":"Primeiro quadro","first-board.line":"Um quadro que acompanha a sua própria construção: cartões, colunas, arrastar e largar, projetos.","team-roles.name":"Equipa e funções","team-roles.line":"Perfis de agentes, modelos de equipa, espaços e quem faz o quê.","install.name":"Instalação e versões","install.line":"Um zip que um amigo instala, com atualização automática, canais e voltar atrás.","usage-saver.name":"Poupança de uso","usage-saver.line":"Medir o custo de cada execução, manter o código enxuto, poupar o teu limite.","friends.name":"Amigos e partilha","friends.line":"DMs privadas, um relay baralhado, convites, funções e projetos partilhados.","languages.name":"Idiomas","languages.line":"Todo o texto dos ecrãs num ficheiro de idioma, começando pelo holandês e o flamengo.","ai-tester.name":"Testador de IA","ai-tester.line":"Um testador verifica cada entrega primeiro e mostra o que viu.","website.name":"O site","website.line":"aigile.lol, a página de apresentação e esta cronologia.","streaming.name":"Chat e emissão","streaming.line":"Discord, Twitch, OBS, modo streamer, GIFs e emojis.","no-ai.name":"Edição sem IA","no-ai.line":"Um quadro para quem programa sem IA, e quadros públicos.","night-watch.name":"Vigia da noite","night-watch.line":"Um vigia e Scrum Master mantêm as equipas no rumo enquanto dormes.","p-more.name":"Tudo o resto","p-more.line":"Ideias mais pequenas ainda à espera da sua vez.","p-android.name":"Telemóvel e Android","p-android.line":"Acede ao teu quadro pelo telemóvel e, depois, numa aplicação Android nativa.","p-release.name":"Alfa e mais além","p-release.line":"Alfa fechado, o site no ar e depois o beta.","p-languages.name":"Mais idiomas","p-languages.line":"Mais de cem idiomas e um modo de imersão para quem está a aprender.","p-engines.name":"Mais motores de IA","p-engines.line":"Escolhe Claude, Codex ou Gemini para cada agente.","p-pro.name":"Prática profissional","p-pro.line":"Etiquetas de risco, portões de merge, cartões de incidente e proteções.","p-self.name":"A cuidar de ti","p-self.line":"Modo cansado, lembretes de autocuidado e 4:20.","p-servers.name":"Servidores e escala","p-servers.line":"Definições globais de servidor, funções e planeamento para crescer.","p-livestream.name":"Extras de emissão","p-livestream.line":"Chat da Twitch, emojis personalizados e uma vista pública em direto."},"words":{"button":"📖 Termos de programação","h":"📖 Termos de programação explicados","intro":"As palavras que os programadores (e as equipas de IA) usam, em linguagem simples.","search":"Pesquisar uma palavra…","none":"Nenhuma palavra corresponde.","close":"Fechar","list":[{"id":"backlog","word":"Backlog","text":"Ideias e trabalho que ainda não foram planeados. Nada ali é trabalhado até passar para A fazer."},{"id":"sprint","word":"Sprint","text":"Um período curto de trabalho (muitas vezes uma ou duas semanas) com um conjunto combinado de cartões para concluir.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"Um ponto de situação rápido: o que cada membro da equipa fez, o que faz a seguir e o que o está a travar.","also":["standup","stand-ups","daily"]},{"id":"bug","word":"Bug","text":"Algo que não funciona como devia.","also":["bugs"]},{"id":"test","word":"Teste","text":"Experimentar um trabalho terminado para verificar se faz o que foi pedido, antes de o aceitares.","also":["testes","testar","testares"],"noTip":1},{"id":"commit","word":"Commit","text":"Um instantâneo guardado do código, com uma nota curta do que mudou. Podes sempre voltar a um deles.","also":["commits"]},{"id":"push","word":"Push","text":"Enviar os instantâneos guardados (commits) deste computador para o GitHub, para ficarem com cópia de segurança e partilhados."},{"id":"branch","word":"Branch","text":"Uma linha de trabalho separada no código, para fazer alterações sem tocar na versão principal.","also":["branches"]},{"id":"merge","word":"Merge","text":"Integrar as alterações de um branch na versão principal."},{"id":"repo","word":"Repo","text":"A pasta de código do projeto e todo o seu histórico de commits, normalmente também guardada no GitHub.","also":["repositório","repository"]},{"id":"refactor","word":"Refactor","text":"Arrumar o código sem mudar o que ele faz: ficheiros mais pequenos, nomes mais claros, menos repetição."},{"id":"deploy","word":"Deploy","text":"Pôr uma nova versão em produção, por exemplo num servidor onde as pessoas a usam."},{"id":"kanban","word":"Kanban","text":"Um quadro com colunas (A fazer, Em curso, Concluído) onde os cartões andam da esquerda para a direita à medida que o trabalho avança."},{"id":"wip","word":"Limite de WIP","text":"Work in progress (trabalho em curso): o máximo de cartões que uma coluna deve ter, para a equipa acabar as coisas antes de começar mais.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Pedir que as alterações de um branch sejam verificadas e integradas na versão principal.","also":["PR"]},{"id":"hook","word":"Hook","text":"Um pequeno comando que corre sozinho num momento definido, por exemplo quando uma sessão de IA começa, para a equipa ouvir os teus comentários.","also":["hooks"]},{"id":"token","word":"Token","text":"A unidade em que o uso da IA é contado: aproximadamente algumas letras de texto lidas ou escritas. Menos tokens, mais do teu plano por gastar.","also":["tokens"]},{"id":"agent","word":"Agente","text":"Uma IA que trabalha sozinha numa tarefa: lê o código, faz alterações, corre verificações e comunica o resultado.","also":["agentes","agent"]}]}};
